// /actions — generated by `pnpm gen:screen actions`, then built from the Actions mockup: every open action
// with an owner and a date, in three columns, the source kept on every card (E5 AC1, AC4). Strings are i18n
// keys; data comes from work.action.list (overdue is computed there, not here).
import { useEffect, useState } from 'react';
import { Button, Card, FormMessage, PageHeader, StatusChip, useI18n } from '@ocs/ui';
import { loadActions, type OpenAction } from '../api.ts';
import { sourceLabel } from '../source.ts';

type State = { kind: 'loading' } | { kind: 'failed' } | { kind: 'loaded'; actions: OpenAction[] };

/** The mockup's columns: open, in progress, and waiting on someone outside OCS. */
const COLUMNS = ['open', 'progress', 'waiting'] as const;
type Column = (typeof COLUMNS)[number];

function columnOf(a: OpenAction): Column {
  if (!('userId' in a.owner)) return 'waiting';
  return a.status === 'in_progress' ? 'progress' : 'open';
}

export function ActionsPage() {
  const { t } = useI18n();
  const [mine, setMine] = useState(false);
  const [state, setState] = useState<State>({ kind: 'loading' });

  useEffect(() => {
    setState({ kind: 'loading' });
    loadActions(mine).then(
      (actions) => {
        setState({ kind: 'loaded', actions });
      },
      () => {
        setState({ kind: 'failed' });
      },
    );
  }, [mine]);

  const filter = (
    <div role="group" aria-label={t('actions.owner')}>
      <Button
        variant={mine ? 'secondary' : 'primary'}
        aria-pressed={!mine}
        onClick={() => {
          setMine(false);
        }}
      >
        {t('actions.all')}
      </Button>{' '}
      <Button
        variant={mine ? 'primary' : 'secondary'}
        aria-pressed={mine}
        onClick={() => {
          setMine(true);
        }}
      >
        {t('actions.mine')}
      </Button>
    </div>
  );

  return (
    <>
      <PageHeader eyebrow={`/ ${t('nav.actions')}`} title={t('actions.heading')} actions={filter} />
      <p>{t('actions.intro')}</p>
      {state.kind === 'loading' ? <p>{t('common.loading')}</p> : null}
      {state.kind === 'failed' ? <FormMessage tone="error">{t('actions.failed')}</FormMessage> : null}
      {state.kind === 'loaded' ? (
        <div className="ocs-board">
          {COLUMNS.map((col) => {
            const cards = state.actions.filter((a) => columnOf(a) === col);
            return (
              <Card
                key={col}
                title={`${t(`actions.col.${col}`)} · ${String(cards.length)}`}
                titleId={`col-${col}`}
              >
                {cards.length === 0 ? <p>{t('actions.none')}</p> : null}
                <ul className="ocs-board__list">
                  {cards.map((a) => (
                    <li key={a.id} className="ocs-board__card">
                      <div className="ocs-board__meta">
                        {a.projectId ?? ''} {a.overdue ? <StatusChip tone="breach" /> : null}
                      </div>
                      <div className="ocs-board__title">{a.title}</div>
                      <div className="ocs-board__meta">
                        {t('actions.ownerDue', { owner: a.owner.name ?? '—', due: a.due })}
                      </div>
                      <div className="ocs-board__meta">{sourceLabel(t, a.source)}</div>
                    </li>
                  ))}
                </ul>
              </Card>
            );
          })}
        </div>
      ) : null}
    </>
  );
}
